<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Playground</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    background: #1a1a2e;
    color: #eee;
    font-family: 'Segoe UI', system-ui, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    user-select: none;
  }

  h1 {
    margin: 0 0 18px;
    font-size: 1.6rem;
    color: #e94560;
    letter-spacing: 1px;
  }

  .controls {
    display: flex;
    gap: 12px;
    margin-bottom: 18px;
  }

  button {
    background: #16213e;
    color: #eee;
    border: 1px solid #0f3460;
    padding: 9px 22px;
    font-size: 0.95rem;
    cursor: pointer;
    border-radius: 6px;
    transition: background 0.2s, box-shadow 0.2s;
  }

  button:hover { background: #0f3460; box-shadow: 0 0 8px rgba(233,69,96,0.3); }
  button:active { transform: scale(0.97); }

  button.active {
    background: #e94560;
    border-color: #e94560;
    box-shadow: 0 0 12px rgba(233,69,96,0.5);
  }

  #sim {
    background: #0a0a1a;
    border: 2px solid #0f3460;
    border-radius: 8px;
    cursor: crosshair;
    display: block;
    box-shadow: 0 0 30px rgba(15,52,96,0.4);
  }

  .info {
    margin-top: 12px;
    font-size: 0.8rem;
    color: #555;
  }
</style>
</head>
<body>

<h1>⚽ Bouncing Ball Playground</h1>

<div class="controls">
  <button id="drop">Drop Ball</button>
  <button id="play">Play</button>
  <button id="clear">Clear</button>
</div>

<canvas id="sim" width="600" height="450"></canvas>
<p class="info">Click the canvas to place a ball. Press Play to animate.</p>

<script>
(function () {
  const canvas = document.getElementById('sim');
  const ctx    = canvas.getContext('2d');
  const btnDrop = document.getElementById('drop');
  const btnPlay = document.getElementById('play');
  const btnClear = document.getElementById('clear');

  /* ---- state ---- */
  let running = false;
  let animId  = null;

  const GRAVITY      = 600;   // px/s²
  const RESTITUTION  = 0.78;
  const BASE_DT      = 1 / 60; // one frame at 60 fps
  const balls        = [];

  /* ---- helpers ---- */
  function randomColor () {
    const palette = [
      '#e94560','#f3a683','#ffb8b8','#ff6f61','#ffcc5c',
      '#ffd166','#06d6a0','#118ab2','#9b5de5','#f15bb5',
      '#7209b7','#4cc9f0','#4361ee','#4895ef'
    ];
    return palette[Math.floor(Math.random() * palette.length)];
  }

  function clampBall (b) {
    b.x = Math.max(b.r, Math.min(canvas.width - b.r, b.x));
    b.y = Math.max(b.r, Math.min(canvas.height - b.r, b.y));
  }

  /* ---- drawing ---- */
  function clearCanvas () {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  }

  function drawBall (b) {
    // Shadow
    ctx.beginPath();
    ctx.arc(b.x + 2, b.y + 2, b.r, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(0,0,0,0.25)';
    ctx.fill();

    // Main circle
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fillStyle = b.color;
    ctx.fill();

    // Specular highlight
    ctx.beginPath();
    const hs = b.r * 0.45;
    ctx.arc(b.x - b.r * 0.32, b.y - b.r * 0.32, hs, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,255,255,0.32)';
    ctx.fill();

    // Thin rim
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255,255,255,0.12)';
    ctx.lineWidth = 1;
    ctx.stroke();
  }

  function render () {
    clearCanvas();
    for (let i = balls.length - 1; i >= 0; i--) drawBall(balls[i]);
  }

  /* ---- physics step ---- */
  function step (dt) {
    if (dt == null || dt === undefined) dt = 1;
    const frameDt = BASE_DT * dt;
    const gravStep = GRAVITY * frameDt;

    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];

      // Gravity
      b.vy += gravStep;

      // Integrate
      b.x += b.vx * frameDt;
      b.y += b.vy * frameDt;

      // --- floor ---
      if (b.y + b.r > canvas.height) {
        b.y = canvas.height - b.r;
        b.vy = -Math.abs(b.vy) * RESTITUTION;
        b.vx *= 0.995;            // slight friction on contact
        if (Math.abs(b.vy) < 6) b.vy = 0;
      }

      // --- ceiling ---
      if (b.y - b.r < 0) {
        b.y = b.r;
        b.vy = Math.abs(b.vy) * RESTITUTION;
      }

      // --- right wall ---
      if (b.x + b.r > canvas.width) {
        b.x = canvas.width - b.r;
        b.vx = -Math.abs(b.vx) * RESTITUTION;
      }

      // --- left wall ---
      if (b.x - b.r < 0) {
        b.x = b.r;
        b.vx = Math.abs(b.vx) * RESTITUTION;
      }
    }

    render();
  }

  /* ---- public API helpers ---- */
  function addBall (x, y, vx, vy, r) {
    const radius = (r != null && typeof r === 'number') ? r : (15 + Math.random() * 20);
    const ball = {
      x:   x != null ? x : canvas.width / 2,
      y:   y != null ? y : canvas.height / 2,
      vx:  vx != null ? Number(vx) : 0,
      vy:  vy != null ? Number(vy) : 0,
      r:   radius,
      color: randomColor()
    };
    clampBall(ball);
    balls.push(ball);
    render();
    return ball;
  }

  function clearBalls () {
    balls.length = 0;
    clearCanvas();
  }

  /* ---- loop control ---- */
  function startLoop () {
    if (running) return;
    let lastTime = performance.now();
    running = true;
    btnPlay.textContent = 'Pause';
    btnPlay.classList.add('active');

    (function tick (now) {
      const rawDt = (now - lastTime) / (BASE_DT * 1000);
      lastTime = now;
      step(Math.min(rawDt, 4));          // cap to avoid spiral of death
      animId = requestAnimationFrame(tick);
    })(performance.now());
  }

  function stopLoop () {
    if (!running) return;
    running = false;
    if (animId) { cancelAnimationFrame(animId); animId = null; }
    btnPlay.textContent = 'Play';
    btnPlay.classList.remove('active');
  }

  /* ---- event wiring ---- */
  btnDrop.addEventListener('click', function () {
    addBall(canvas.width / 2, 40);
  });

  btnPlay.addEventListener('click', function () {
    running ? stopLoop() : startLoop();
  });

  btnClear.addEventListener('click', clearBalls);

  canvas.addEventListener('click', function (e) {
    const rect = canvas.getBoundingClientRect();
    const sx   = canvas.width  / rect.width;
    const sy   = canvas.height / rect.height;
    const cx   = (e.clientX - rect.left) * sx;
    const cy   = (e.clientY - rect.top)  * sy;
    addBall(cx, cy);
  });

  /* ---- expose window.sim API ---- */
  window.sim = {
    get w () { return canvas.width; },
    get h () { return canvas.height; },

    balls: function () {
      return balls.map(function (b) { return { x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r }; });
    },

    addBall: addBall,
    clear:   clearBalls,
    step:    step
  };

  render(); // initial clear
})();
</script>

</body>
</html>
